-- Service divisions & services
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_web_development', 'web-development', 'Web Development & Digital Solutions', 'Business websites, e-commerce and web applications that load fast and are easy to update.', '<p>We design and build websites and web applications for organisations that need more than a brochure. Every site is responsive, fast on mobile data, search-friendly and set up so your team can update content without calling us.</p><p>For larger needs we build web applications, portals and dashboards on the same foundations: secure sign-in, role-based access, audit trails and local payment options.</p>', '[{"title":"Fast on real networks","body":"Pages are built to load quickly on mobile data, with optimised images and minimal scripts."},{"title":"Easy to update","body":"A content editor lets your team change text, images and announcements without technical help."},{"title":"Found on search","body":"Clean structure, metadata, sitemaps and Search Console setup so people can find you."},{"title":"Ready to take payments","body":"Accept EcoCash, OneMoney, InnBucks and cards through Paynow when you need to sell online."}]', '["Responsive design for phones, tablets and desktops","Content management so your team can edit pages","On-page SEO, sitemap and Google Search Console setup","Analytics dashboard","Hosting, SSL certificate and domain setup","Training session and handover notes"]', '[{"q":"Can I update the website myself?","a":"Yes. Business and e-commerce sites include a content editor. We show your team how to use it during handover."},{"q":"Do you build on WordPress?","a":"We choose the platform that fits the job. For most business sites we use a modern, lightweight stack that is fast and secure; where WordPress is the better fit, we will say so in the quotation."},{"q":"Who owns the website?","a":"You do. On full payment, the content, design and code we wrote for you are yours, as set out in our service terms."}]', 'globe', 'active', 1, 10, 'Website & Web Application Development', 'Business websites, e-commerce stores and web applications for organisations in Zimbabwe and across Africa. Fast, secure and easy to update.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_web_development__business_websites', 'scat_web_development', 'business-websites', 'Corporate & business websites', 'Professional sites that explain what you do and turn visitors into enquiries.', 'custom_quote', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_web_development__e_commerce', 'scat_web_development', 'e-commerce', 'E-commerce platforms', 'Online stores with product catalogues, stock and local payment methods.', 'custom_quote', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_web_development__web_applications', 'scat_web_development', 'web-applications', 'Web applications', 'Browser-based systems built around your processes, with secure user accounts.', 'custom_quote', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_web_development__portals', 'scat_web_development', 'portals', 'Customer & employee portals', 'Self-service areas where clients or staff can see documents, requests and status.', 'custom_quote', 'active', 40);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_web_development__dashboards', 'scat_web_development', 'dashboards', 'Custom dashboards', 'One screen that brings together the numbers your team checks every day.', 'custom_quote', 'active', 50);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_web_development__redesign_optimisation', 'scat_web_development', 'redesign-optimisation', 'Website redesign & optimisation', 'Faster, clearer, better-ranking versions of existing websites.', 'custom_quote', 'active', 60);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_mobile_desktop_apps', 'mobile-desktop-apps', 'Mobile & Desktop Application Development', 'Android, iOS and desktop apps built for real networks and real devices.', '<p>We build mobile and desktop applications that work well on the devices your users actually have, including mid-range Android phones and patchy connections. Apps can work offline and sync when a connection returns.</p><p>We handle design, development, testing, app store publishing and the back-end services the app depends on.</p>', '[{"title":"One codebase where it makes sense","body":"Cross-platform builds reach Android and iOS together, which keeps cost and maintenance down."},{"title":"Offline-capable","body":"Apps can keep working without signal and sync data when the connection returns."},{"title":"Store-ready","body":"We prepare listings, screenshots and releases for Google Play and the App Store."},{"title":"Connected to your systems","body":"Apps talk to your existing databases, payment methods and business software through secure APIs."}]', '["User experience and interface design","Android and/or iOS app, or a desktop app for Windows and macOS","Back-end API and admin dashboard where needed","Testing on real devices","App store publishing support","Source code and documentation on full payment"]', '[{"q":"Should we build for Android or iPhone first?","a":"In Zimbabwe most users are on Android, so many projects start there. A cross-platform build lets you cover both at little extra cost; we will recommend an approach after discovery."},{"q":"Can the app work without internet?","a":"Yes. Offline support is planned during design so data is stored safely on the device and synced later."}]', 'smartphone', 'active', 1, 20, 'Mobile & Desktop App Development', 'Android, iOS, Windows and macOS applications built for real networks, with offline support, app store publishing and secure back-ends.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_mobile_desktop_apps__android', 'scat_mobile_desktop_apps', 'android', 'Android apps', 'Native-quality Android apps tuned for the phones your customers use.', 'custom_quote', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_mobile_desktop_apps__ios', 'scat_mobile_desktop_apps', 'ios', 'iOS apps', 'iPhone and iPad apps published through the App Store.', 'custom_quote', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_mobile_desktop_apps__windows', 'scat_mobile_desktop_apps', 'windows', 'Windows applications', 'Desktop software for offices, counters and back-office teams.', 'custom_quote', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_mobile_desktop_apps__macos', 'scat_mobile_desktop_apps', 'macos', 'macOS applications', 'Desktop tools for teams working on Mac.', 'custom_quote', 'active', 40);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_mobile_desktop_apps__cross_platform', 'scat_mobile_desktop_apps', 'cross-platform', 'Cross-platform apps', 'One codebase for Android and iOS to reach both audiences efficiently.', 'custom_quote', 'active', 50);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_mobile_desktop_apps__enterprise_apps', 'scat_mobile_desktop_apps', 'enterprise-apps', 'Custom enterprise applications', 'Field, sales and operations apps connected to your internal systems.', 'custom_quote', 'active', 60);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_business_software', 'business-software', 'Business Software & Enterprise Systems', 'ERP, POS, inventory, HR and CRM systems shaped around how your organisation works.', '<p>Off-the-shelf software often forces you to change how you work. We build business systems around your processes instead: point of sale, stock control, HR and payroll records, customer management and full ERP platforms.</p><p>Systems support multiple branches and currencies, keep an audit trail of changes and can connect to the tools you already use.</p>', '[{"title":"Fits your process","body":"Workflows, approvals and reports follow how your team already works."},{"title":"Multi-currency by design","body":"USD and ZWG amounts are kept separate and reported correctly."},{"title":"Clear audit trail","body":"Every important change records who did it and when."},{"title":"Grows in stages","body":"Start with the module you need most and add others as you grow."}]', '["Process mapping and requirements document","Web-based system with role-based access","Data migration from spreadsheets or existing systems","Reports and exports","Staff training and user guides","Support and maintenance options after launch"]', '[{"q":"Can you move our data from spreadsheets?","a":"Yes. Data migration is part of most projects. We clean and import your existing records and check the totals with you before go-live."},{"q":"Does it work across branches?","a":"Yes. Systems can run across several branches with each user seeing only what their role allows."}]', 'layers', 'active', 1, 30, 'Business Software, ERP & POS Systems', 'Custom ERP, point of sale, inventory, HR and CRM systems built around your processes, with multi-currency support and audit trails.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_business_software__erp', 'scat_business_software', 'erp', 'Custom ERP', 'One system for sales, purchasing, stock, finance and people.', 'custom_quote', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_business_software__pos', 'scat_business_software', 'pos', 'POS systems', 'Fast checkout for shops and counters, with receipts and daily reconciliation.', 'custom_quote', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_business_software__inventory_warehouse', 'scat_business_software', 'inventory-warehouse', 'Inventory & warehouse', 'Stock levels, transfers and reorder alerts across locations.', 'custom_quote', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_business_software__hr_payroll', 'scat_business_software', 'hr-payroll', 'HR & payroll', 'Employee records, leave and payroll calculations in one place.', 'custom_quote', 'active', 40);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_business_software__crm', 'scat_business_software', 'crm', 'CRM', 'Track leads, customers, follow-ups and sales conversations.', 'custom_quote', 'active', 50);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_business_software__business_platforms', 'scat_business_software', 'business-platforms', 'Business management platforms', 'Purpose-built systems for the way your sector operates.', 'custom_quote', 'active', 60);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_ai_data', 'ai-data', 'AI, Data & Intelligence', 'Dashboards, analytics and practical AI features that answer real business questions.', '<p>Most organisations already hold the data they need to make better decisions; it is just spread across systems and spreadsheets. We bring it together, clean it and present it in dashboards your team will use.</p><p>Where AI helps, we add it in practical ways: assistants that answer questions about your documents, extraction of data from invoices and forms, and forecasts based on your history.</p>', '[{"title":"Decisions from facts","body":"Dashboards built on clean, reconciled data from your own systems."},{"title":"Less manual capture","body":"Document processing extracts data from forms, receipts and invoices."},{"title":"Practical AI","body":"Assistants and automations are scoped to clear tasks, with human review where it matters."},{"title":"Your data stays yours","body":"We design for privacy and follow Zimbabwe’s Cyber and Data Protection Act."}]', '["Data audit and connection to your sources","Business intelligence dashboards","Scheduled reports","AI assistant or document-processing pilot where relevant","Documentation of data flows and access"]', '[{"q":"Do we need a lot of data to use AI?","a":"Not always. Many useful features, such as document extraction or a question-answering assistant over your policies, work with the documents you already have."},{"q":"Which tools do you use for dashboards?","a":"We use the tool that fits your budget and team, from custom web dashboards to established BI platforms."}]', 'line-chart', 'active', 1, 40, 'AI, Data Analytics & Business Intelligence', 'Business intelligence dashboards, analytics, predictive models and practical AI features such as document processing and assistants.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_ai_data__ai_applications', 'scat_ai_data', 'ai-applications', 'AI-powered applications', 'Assistants and features that use AI for a clear, measurable task.', 'custom_quote', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_ai_data__data_analytics', 'scat_ai_data', 'data-analytics', 'Data analytics', 'Analysis of your sales, operations and customer data.', 'custom_quote', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_ai_data__business_intelligence', 'scat_ai_data', 'business-intelligence', 'Business intelligence', 'Dashboards that combine data from several systems in one view.', 'custom_quote', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_ai_data__predictive_analytics', 'scat_ai_data', 'predictive-analytics', 'Predictive analytics', 'Forecasts for demand, cash flow or churn based on your history.', 'custom_quote', 'active', 40);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_ai_data__data_processing', 'scat_ai_data', 'data-processing', 'Data processing', 'Cleaning, merging and moving data between systems reliably.', 'custom_quote', 'active', 50);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_ai_data__document_processing', 'scat_ai_data', 'document-processing', 'Intelligent document processing', 'Extract data from invoices, forms and receipts automatically.', 'custom_quote', 'active', 60);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_automation_integration', 'automation-integration', 'Automation & Systems Integration', 'APIs, payment gateways and workflows that remove manual steps between systems.', '<p>When systems do not talk to each other, people re-type data, chase approvals and reconcile by hand. We connect your systems through APIs and automate the repetitive steps in between.</p><p>We have deep experience with Zimbabwean payment rails, including Paynow, PesePay, EcoCash, OneMoney, InnBucks and card payments, and build integrations that confirm every payment before it is recorded.</p>', '[{"title":"Fewer manual steps","body":"Automated workflows move data and approvals without re-typing."},{"title":"Reliable payments","body":"Gateway integrations verify every payment with the provider before marking it paid."},{"title":"Systems that agree","body":"Integrations keep records consistent across your tools."},{"title":"Room to change","body":"Clean, documented APIs make it easier to swap or add systems later."}]', '["Integration design and documentation","REST APIs with authentication and rate limiting","Payment gateway integration with reconciliation","Automated workflows and notifications","Monitoring and error alerts"]', '[{"q":"Can you add EcoCash and card payments to our existing website?","a":"Yes. We integrate Paynow or PesePay into existing sites and systems, including payment confirmation and receipts."},{"q":"What happens if an integration fails?","a":"Integrations retry safely and alert your team, so nothing is lost or processed twice."}]', 'workflow', 'active', 1, 50, 'Automation, API Development & Payment Integration', 'Business process automation, API development and payment gateway integration with Paynow, PesePay, EcoCash, OneMoney, InnBucks and cards.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_automation_integration__process_automation', 'scat_automation_integration', 'process-automation', 'Business process automation', 'Automate approvals, reminders and hand-offs between teams.', 'custom_quote', 'active', 10);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_automation_integration__api_development', 'scat_automation_integration', 'api-development', 'API development', 'Secure, documented APIs for your apps, partners and systems.', 'custom_quote', 'active', 20);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_automation_integration__third_party_integrations', 'scat_automation_integration', 'third-party-integrations', 'Third-party integrations', 'Connect accounting, CRM, email and other services you rely on.', 'custom_quote', 'active', 30);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_automation_integration__payment_gateways', 'scat_automation_integration', 'payment-gateways', 'Payment gateway integration', 'Paynow, PesePay, EcoCash, OneMoney, InnBucks and cards, with reconciliation.', 'custom_quote', 'active', 40);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_automation_integration__workflow_automation', 'scat_automation_integration', 'workflow-automation', 'Workflow automation', 'Rules that move work forward automatically and notify the right people.', 'custom_quote', 'active', 50);
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_automation_integration__system_modernisation', 'scat_automation_integration', 'system-modernisation', 'System modernisation', 'Move ageing systems to maintainable, secure platforms in stages.', 'custom_quote', 'active', 60);
INSERT OR IGNORE INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_cloud_it', 'cloud-it', 'Cloud, Infrastructure & IT Solutions', 'Hosting, business email, domains, backups and technical support.', '<p>We set up and look after the infrastructure your business depends on: cloud hosting, domains, professional email on your own domain, databases, backups and day-to-day technical support.</p><p>You get clear ownership of every account, renewal reminders before anything expires, and a named contact when something needs fixing.</p>', '[{"title":"Professional email","body":"Addresses on your own domain with spam filtering and phone access."},{"title":"Nothing expires by surprise","body":"We track domain, hosting and certificate renewals and remind you in advance."},{"title":"Backups you can restore","body":"Scheduled backups are tested, not just taken."},{"title":"Support when you need it","body":"Retainer or ad-hoc support with clear response targets."}]', '["Cloud deployment and configuration","Domain registration and DNS management","Business email setup, including SPF, DKIM and DMARC","Database setup and maintenance","Backup schedule with restore tests","Technical support plan"]', '[{"q":"Can you move our existing email to our own domain?","a":"Yes. We set up the new mailboxes, configure DNS, migrate existing mail and help your team set up their phones."},{"q":"Who owns the domain?","a":"Your organisation is the registered owner. We manage it on your behalf if you want us to."}]', 'cloud', 'active', 1, 60, 'Cloud Hosting, Business Email, Domains & IT Support', 'Cloud deployment, domain registration, business email on your own domain, backups and technical support for organisations in Zimbabwe.');
INSERT OR IGNORE INTO services (id, category_id, slug, name, summary, pricing_model, status, sort_order) VALUES ('svc_cloud_it__cloud_deployment', 'scat_cloud_it', 'cloud-deployment', 'Cloud deployment', 'Host applications and websites on reliable cloud infrastructure.', 'custom_quote', 'active', 10);
