INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_home__hero', 'pag_home', 'hero', 'hero', 10, 1, '{"eyebrow":"Technology partner for growing organisations","title":"Building intelligent digital solutions.","body":"Kuzikode designs, builds and runs websites, apps and business software for organisations in Zimbabwe and across Africa.","primaryCta":{"label":"Start a project","href":"/start-a-project"},"secondaryCta":{"label":"Explore services","href":"/services"}}', '{"eyebrow":"Technology partner for growing organisations","title":"Building intelligent digital solutions.","body":"Kuzikode designs, builds and runs websites, apps and business software for organisations in Zimbabwe and across Africa.","primaryCta":{"label":"Start a project","href":"/start-a-project"},"secondaryCta":{"label":"Explore services","href":"/services"}}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_home__services', 'pag_home', 'services', 'services_grid', 20, 1, '{"title":"What we do","intro":"Six areas of work, one team. Start with what you need now and add more as you grow."}', '{"title":"What we do","intro":"Six areas of work, one team. Start with what you need now and add more as you grow."}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO website_sections (id, page_id, key, type, position, visible, draft_content, published_content, published_at) VALUES ('sec_home__why', 'pag_home', 'why', 'features', 30, 1, '{"title":"Why Kuzikode","intro":"How we approach every project, whatever its size.","items":[{"icon":"wallet","title":"Built for local rails","body":"EcoCash, OneMoney, InnBucks and cards through Paynow, with every payment confirmed before it is recorded."},{"icon":"gauge","title":"Fast on real networks","body":"Pages and apps are built to load quickly on mobile data and mid-range phones."},{"icon":"list-checks","title":"Clear scope, fixed milestones","body":"A written quotation, agreed milestones and weekly updates in your client portal."},{"icon":"life-buoy","title":"Support after launch","body":"A support period on every project, with care plans for ongoing updates and monitoring."}]}', '{"title":"Why Kuzikode","intro":"How we approach every project, whatever its size.","items":[{"icon":"wallet","title":"Built for local rails","body":"EcoCash, OneMoney, InnBucks and cards through Paynow, with every payment confirmed before it is recorded."},{"icon":"gauge","title":"Fast on real networks","body":"Pages and apps are built to load quickly on mobile data and mid-range phones."},{"icon":"list-checks","title":"Clear scope, fixed milestones","body":"A written quotation, agreed milestones and weekly updates in your client portal."},{"icon":"life-buoy","title":"Support after launch","body":"A support period on every project, with care plans for ongoing updates and monitoring."}]}', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
